/**
 * The MAGENTA lockup, inlined.
 *
 * Inlined rather than served as <img> so the artwork inherits currentColor -
 * the same file has to sit white on the magenta header and white on the ink
 * footer, and a baked-in fill would go invisible the moment either ground
 * changes. Source artwork is 1200x600 with the mark floating in the middle of
 * it; the viewBox below is cropped to the ink so the lockup can be sized by
 * height alone with no phantom padding around it.
 *
 * The link that wraps this carries the accessible name, so the drawing itself
 * is hidden from assistive technology.
 *
 * Args (via set_query_var / get_template_part $args):
 *   tagline (bool) - include the CREATIVE STUDIO line. Default true.
 *
 * @package Magenta
 */

if ( ! defined( 'ABSPATH' ) ) {
	exit;
}

